# ============================================================
# 🪵 로그 버퍼링 문제 해결
# ------------------------------------------------------------
# Render 같은 호스팅 환경은 stdout이 터미널이 아니라 파이프로 연결되기 때문에,
# Python이 기본적으로 stdout을 "블록 버퍼링"합니다. 그러면 print()로 찍은 로그가
# 버퍼가 다 찰 때까지(혹은 프로세스가 종료될 때까지) 실제로 화면에 나타나지 않아서,
# 코드는 정상 실행 중인데도 로그창에는 아무것도 안 찍히는 것처럼 보입니다.
# (반면 werkzeug의 요청 로그 "GET / HTTP/1.1 200"은 logging 모듈로 stderr에 즉시
# 나가기 때문에 항상 먼저/제대로 보입니다.)
# 아래 두 줄로 stdout/stderr을 줄 단위 버퍼링으로 강제해서 print() 로그가
# 지연 없이 바로바로 출력되게 합니다.
# ============================================================
try:
    sys.stdout.reconfigure(line_buffering=True)
    sys.stderr.reconfigure(line_buffering=True)
except Exception:
    pass  # 일부 실행 환경(예: 특정 IDE)에서는 reconfigure가 없을 수 있어 안전하게 무시

# ------------------------------------------------------------
# 🚨 더 확실한 이중 안전장치
# 위 reconfigure()만으로 여전히 로그가 하나도 안 보이는 사례가 있어서,
# 아예 이 파일의 모든 print()를 "stderr로 + 매번 즉시 flush" 하도록 덮어씁니다.
# werkzeug 접속 로그(GET / HTTP/1.1 200)가 항상 바로바로 보였던 걸 보면
# stderr 채널 자체는 문제없이 호스팅 로그창에 나오고 있다는 뜻이므로,
# print()도 같은 채널을 타게 만들면 버퍼링 문제와 무관하게 무조건 보입니다.
# ------------------------------------------------------------
import builtins as _builtins
_original_print = _builtins.print


def print(*args, **kwargs):
    kwargs.setdefault("file", sys.stderr)
    kwargs.setdefault("flush", True)
    _original_print(*args, **kwargs)

# ============================================================
# 환경설정 - BOT_TOKEN, CHAT_ID, DART_API_KEY 설정
# ============================================================
# ============================================================
# 🔑 환경설정 - BOT_TOKEN, CHAT_ID, DART_API_KEY 등
# ------------------------------------------------------------
# 보안을 위해 코드에 직접 값을 적지 않고, 실행 환경의 "환경변수"에서
# 읽어옵니다. 로컬 컴퓨터에서 테스트할 땐 아래처럼 실행 전에 값을 넣어주면 됩니다.
#   (Windows PowerShell)  $env:BOT_TOKEN="여기에토큰"
#   (Mac/Linux)           export BOT_TOKEN="여기에토큰"
# Cloud Run에 배포할 땐 Secret Manager로 등록해서 자동으로 주입합니다
# (배포 가이드 참고).
# ============================================================
BOT_TOKEN = os.environ.get("BOT_TOKEN", "")
CHAT_ID = os.environ.get("CHAT_ID", "")
# 🌏 해외뉴스/아침브리핑을 별도 채팅방으로 보내고 싶으면 이 환경변수를 설정.
# 설정 안 하면(빈 값이면) 기존처럼 메인 CHAT_ID로 그대로 감 - 안 건드리면 안전.
CHAT_ID_OVERSEAS = os.environ.get("CHAT_ID_OVERSEAS", "") or CHAT_ID


# ============================================================
# 🎛️ 기능별 ON/OFF 스위치
# ------------------------------------------------------------
# 한 파일 안에서, "이번엔 해외뉴스만 켜서 완성될 때까지 고치고, 그 다음엔
# 해외뉴스 끄고 DART공시만 켜서 고치고..." 이런 식으로 부분별로 하나씩
# 검증하고 싶을 때 씀. 전부 True로 두면 지금까지처럼 다 켜진 원래 봇 그대로.
#
# 🔧 Render 환경변수로 켜고 끕니다 (코드를 안 고쳐도 됨):
#   ENABLE_US_NEWS=true, ENABLE_DOMESTIC_NEWS=false, ... 이런 식으로 설정.
#   환경변수를 안 넣으면 기본값(아래 default)을 따름 - 기본값은 전부 True라서,
#   아무것도 안 건드리면 지금까지와 완전히 동일하게 작동합니다.
# ============================================================
def _env_flag(name, default=True):
    val = os.environ.get(name)
    if val is None:
        return default
    return val.strip().lower() in ("true", "1", "yes", "on")


ENABLE_DOMESTIC_NEWS = _env_flag("ENABLE_DOMESTIC_NEWS")         # 국내 RSS
ENABLE_US_NEWS = _env_flag("ENABLE_US_NEWS")                     # 해외 RSS
ENABLE_MORNING_BRIEFING = _env_flag("ENABLE_MORNING_BRIEFING")   # 아침 브리핑(해외지수/테마)
ENABLE_TELEGRAM_CHANNELS = _env_flag("ENABLE_TELEGRAM_CHANNELS") # 텔레그램1(필터)+2(무조건)
ENABLE_CUSTOM_SOURCES = _env_flag("ENABLE_CUSTOM_SOURCES")       # 약업신문/전자신문
ENABLE_DART = _env_flag("ENABLE_DART")                           # DART 공시
ENABLE_NAVER_NEWS = _env_flag("ENABLE_NAVER_NEWS")               # 네이버 뉴스
ENABLE_BLOG = _env_flag("ENABLE_BLOG")                           # 분석 블로그
ENABLE_YOUTUBE = _env_flag("ENABLE_YOUTUBE")                     # 유튜브
ENABLE_SCHEDULE_REMINDERS = _env_flag("ENABLE_SCHEDULE_REMINDERS")  # 일정 D-7/D-3 리마인더
ENABLE_IPO_ALERTS = _env_flag("ENABLE_IPO_ALERTS")               # 신규상장(IPO) 알림

# 🎛️🎯 [단축 스위치] 매번 10개씩 하나하나 끄고 켜는 게 번거로우니, 환경변수
# SOLO_MODE에 딱 하나만 넣으면 "그것만 켜고 나머지는 자동으로 다 끔".
# 예: Render 환경변수에 SOLO_MODE=DART 하나만 넣으면 공시만 켜집니다.
# 다시 전체 모드로 돌아가려면 SOLO_MODE를 지우거나 빈 값으로 두면 됩니다.
#   SOLO_MODE=DOMESTIC_NEWS   → 국내RSS만
#   SOLO_MODE=US_NEWS         → 해외RSS + 아침브리핑만 (같이 다루는 게 자연스러워서 묶음)
#   SOLO_MODE=DART            → DART공시만
#   SOLO_MODE=TELEGRAM        → 텔레그램1+2만
#   SOLO_MODE=CUSTOM_SOURCES  → 약업신문/전자신문만
#   SOLO_MODE=NAVER           → 네이버뉴스만
#   SOLO_MODE=BLOG            → 분석블로그만
#   SOLO_MODE=YOUTUBE         → 유튜브만
_SOLO_MODE = os.environ.get("SOLO_MODE", "").strip().upper()
if _SOLO_MODE:
    # 일단 전부 끄고, SOLO_MODE에 해당하는 것만 켬
    ENABLE_DOMESTIC_NEWS = False
    ENABLE_US_NEWS = False
    ENABLE_MORNING_BRIEFING = False
    ENABLE_TELEGRAM_CHANNELS = False
    ENABLE_CUSTOM_SOURCES = False
    ENABLE_DART = False
    ENABLE_NAVER_NEWS = False
    ENABLE_BLOG = False
    ENABLE_YOUTUBE = False
    ENABLE_SCHEDULE_REMINDERS = False
    ENABLE_IPO_ALERTS = False

    if _SOLO_MODE == "DOMESTIC_NEWS":
        ENABLE_DOMESTIC_NEWS = True
    elif _SOLO_MODE == "US_NEWS":
        ENABLE_US_NEWS = True
        ENABLE_MORNING_BRIEFING = True
    elif _SOLO_MODE == "DART":
        ENABLE_DART = True
    elif _SOLO_MODE == "TELEGRAM":
        ENABLE_TELEGRAM_CHANNELS = True
    elif _SOLO_MODE == "CUSTOM_SOURCES":
        ENABLE_CUSTOM_SOURCES = True
    elif _SOLO_MODE == "NAVER":
        ENABLE_NAVER_NEWS = True
    elif _SOLO_MODE == "BLOG":
        ENABLE_BLOG = True
    elif _SOLO_MODE == "YOUTUBE":
        ENABLE_YOUTUBE = True
    else:
        print(f"⚠️ SOLO_MODE='{_SOLO_MODE}'는 알 수 없는 값입니다. 전부 꺼진 상태로 시작합니다. "
              f"(DOMESTIC_NEWS/US_NEWS/DART/TELEGRAM/CUSTOM_SOURCES/NAVER/BLOG/YOUTUBE 중 하나로 입력해주세요)")

DART_API_KEY = os.environ.get("DART_API_KEY", "")
NAVER_CLIENT_ID = os.environ.get("NAVER_CLIENT_ID", "")
NAVER_CLIENT_SECRET = os.environ.get("NAVER_CLIENT_SECRET", "")

if not BOT_TOKEN or not CHAT_ID:
    raise SystemExit(
        "❌ BOT_TOKEN / CHAT_ID가 비어 있습니다.\n"
        "   환경변수(BOT_TOKEN, CHAT_ID)에 값을 설정해주세요. (코드에 직접 적지 않습니다)"
    )

