# 유틸 함수
# ============================================================
def is_us_market_hour(now=None):
    now = now or datetime.datetime.now()
    hour = now.hour
    if US_MARKET_START_HOUR > US_MARKET_END_HOUR:
        return hour >= US_MARKET_START_HOUR or hour < US_MARKET_END_HOUR
    return US_MARKET_START_HOUR <= hour < US_MARKET_END_HOUR


def format_title(title):
    """
    제목 하이라이트 규칙:
      - 유명인물(트럼프, 파월, 젠슨 황 등) -> 🕵️ 접두사만
      - 우리나라 대기업 그룹명(삼성, SK, LG, 한화 등) -> 👍 접두사만
      - 해외 글로벌기업명(엔비디아, 애플 등) -> ⭐ 접두사만
      - 그 외 상장기업/개별 계열사명(삼성전자 등) -> ⚡️로 양쪽 감싸기
      - FED/POWELL/EARNINGS 같은 금리·실적 매크로 단어 -> 💰 접두사
      - TRUMP(영문 티커)는 회사가 아니라 인물이므로 🕵️로 처리
    """
    formatted = html.escape(title)

    money_macro_words = {"FED", "POWELL", "EARNINGS"}
    people_target_words = {"TRUMP"}

    # 1) 유명인물 (한글) -> 🕵️
    for term in sorted(UNIQUE_CELEBS, key=len, reverse=True):
        pattern = re.compile(re.escape(term), re.IGNORECASE)
        formatted = pattern.sub(f"<b>🕵️{term}</b>", formatted)

    # 2) TRUMP(영문)도 인물이므로 🕵️
    for term in sorted(people_target_words):
        pattern = re.compile(r"\b" + re.escape(term) + r"\b", re.IGNORECASE)
        formatted = pattern.sub(f"<b>🕵️{term}</b>", formatted)

    # 3) 금리/실적 매크로 단어 -> 💰
    for term in sorted(money_macro_words):
        pattern = re.compile(r"\b" + re.escape(term) + r"\b", re.IGNORECASE)
        formatted = pattern.sub(f"<b>💰{term}</b>", formatted)

    # 4-a) 우리나라 대기업 그룹명 -> 👍 / 해외 글로벌기업명 -> ⭐
    already_highlighted = set()
    if KOREAN_GROUP_NAMES:
        sorted_terms = sorted(KOREAN_GROUP_NAMES, key=len, reverse=True)
        pattern_parts = [
            (r"\b" + re.escape(t) + r"\b") if t.isascii() else re.escape(t)
            for t in sorted_terms
        ]
        combined_pattern = re.compile("|".join(pattern_parts), re.IGNORECASE)
        formatted = combined_pattern.sub(lambda m: f"<b>👍{m.group(0)}</b>", formatted)
        already_highlighted |= KOREAN_GROUP_NAMES

    if GLOBAL_COMPANY_KEYWORDS:
        sorted_terms = sorted(GLOBAL_COMPANY_KEYWORDS, key=len, reverse=True)
        pattern_parts = [
            (r"\b" + re.escape(t) + r"\b") if t.isascii() else re.escape(t)
            for t in sorted_terms
        ]
        combined_pattern = re.compile("|".join(pattern_parts), re.IGNORECASE)
        formatted = combined_pattern.sub(lambda m: f"<b>⭐{m.group(0)}</b>", formatted)
        already_highlighted |= GLOBAL_COMPANY_KEYWORDS

    # 4-b) 그 외 상장기업명 -> ⚡️로 양쪽 감싸기
    #    (해외 티커 + KRX 전체 상장사명. 4-a에서 이미 👍 처리된 이름은 제외해서 이중 표시 방지)
    #    한 패스로 처리하는 이유: 여러 번 나눠서 치환하면 이미 감싸진 태그 안쪽까지 건드려서 깨지는 문제가 생길 수 있음.
    company_terms = (
        (UNIQUE_TARGET - money_macro_words - people_target_words) | (ALL_LISTED_COMPANIES - NOISY_LISTED_COMPANY_NAMES)
    ) - already_highlighted
    if company_terms:
        sorted_terms = sorted(company_terms, key=len, reverse=True)
        pattern_parts = [
            (r"\b" + re.escape(t) + r"\b") if t.isascii() else re.escape(t)
            for t in sorted_terms
        ]
        combined_pattern = re.compile("|".join(pattern_parts), re.IGNORECASE)
        formatted = combined_pattern.sub(lambda m: f"<b>⚡️{m.group(0)}</b>", formatted)

    # 5) 실적/금리/유가/머니 관련 단어(제목 본문 안에서) -> 💰 접두사
    money_body_words = MONEY_STRONG_WORDS | {"실적", "금리", "유가"}
    for term in sorted(money_body_words, key=len, reverse=True):
        pattern = re.compile(re.escape(term))
        formatted = pattern.sub(f"<b>💰{term}</b>", formatted)

    # 6) 일정 단어(제목 본문 안에서) -> ⏰ 접두사
    formatted = re.sub(re.escape("일정"), "<b>⏰일정</b>", formatted)

    # 7) KEYWORDS_1(내용 키워드1)의 테마 단어 -> 💡 접두사
    #    (기업/인물 이름은 위에서 이미 👍⚡️🕵️로 처리됐으니, 여기선 신약/임상/반도체 같은 순수 테마 단어만 대상)
    #    ⚠️ 예전엔 🎯를 썼는데, DART 공시 카드의 "🎯괴리율"이랑 겹쳐서 헷갈려서 💡로 바꿈
    theme_only_keywords_1 = UNIQUE_KEYWORDS_1 - UNIQUE_GIANTS - UNIQUE_CELEBS - money_body_words - {"일정"}
    if theme_only_keywords_1:
        sorted_terms = sorted(theme_only_keywords_1, key=len, reverse=True)
        pattern_parts = [
            (r"\b" + re.escape(t) + r"\b") if t.isascii() else re.escape(t)
            for t in sorted_terms
        ]
        combined_pattern = re.compile("|".join(pattern_parts), re.IGNORECASE)
        formatted = combined_pattern.sub(lambda m: f"<b>💡{m.group(0)}</b>", formatted)

    return formatted


# ============================================================
# 🧮 중요도 점수 (100점 만점) + [요점] 한 줄 요약
# ------------------------------------------------------------
# 배점 구성 (합계 100점):
#   기본 10점
#   + 매칭 키워드 개수 × 4점 (최대 5개 = 20점)
#   + 상장기업명 직접 언급 15점
#   + 단독 15점 / 속보 15점 / 특징주 15점 (해당하는 것마다 누적)
#   + 계약금액 비율 보너스 (매출액 또는 시가총액 대비, 최대 20점)
#     30%이상 20점 / 15%이상 15점 / 5%이상 10점 / 5%미만 5점
#   → 100점 넘으면 100으로 자름
#
# 등급: 90+ 🔥🔥🔥S   80+ 🔥🔥A+   70+ 🔥A   55+ 🟢B   40+ 🟡C   미만 ⚪D
# ============================================================
CONTRACT_KEYWORDS = {"공급계약", "수주", "계약체결", "공급 계약", "단일판매"}


def _build_key_point_line(title, is_disclosure, highlight_suffix):
    """
    제목 밑에 붙일 "💡[요점]" 한 줄을 만든다. 계약/수주 관련 뉴스면 계약금액이
    무엇과 비교했을 때(비교기준: 매출액 우선, 없으면 시가총액) 몇 %인지
    항상 "비교기준"을 명시해서 보여준다. 계산할 재료가 없으면 None (이 경우
    [요점] 줄 자체를 안 붙임 - 숫자를 지어내지 않는다는 원칙).

    형식: 💡[요점] 계약금액 {금액} · 비교기준 {매출액/시가총액} · 비율 {NN.N%}
    """
    # 📋 DART 공시는 이미 원문에서 "매출액대비" 비율을 직접 뽑아서
    # highlight_suffix에 넣어주고 있으므로(단일판매공급계약 공시는 법적으로
    # 이 비율을 명시해야 함), 그 안의 퍼센트 숫자만 재사용해서 같은 형식으로 통일.
    if is_disclosure and highlight_suffix and "매출액대비" in highlight_suffix:
        for line in highlight_suffix.split("\n"):
            if "매출액대비" in line:
                pct_match = re.search(r"(\d+(?:\.\d+)?)\s*%", line)
                if pct_match:
                    return f"💡[요점] 비교기준 매출액 · 비율 {float(pct_match.group(1)):.1f}%"
                return f"💡[요점] {line.strip()}"
        return None

    if not any(kw in title for kw in CONTRACT_KEYWORDS):
        return None

    amounts = _dart_extract_eok_amounts(title)
    if not amounts:
        return None
    amount = max(amounts)
    amount_label = _eok_comma_label(amount)

    matched_company, stock_code = resolve_primary_company(title)
    if not stock_code:
        return f"💡[요점] 계약금액 {amount_label} · 비교기준 없음(종목 미확인)"

    revenue = _dart_recent_revenue_eok(stock_code)
    if revenue and revenue > 0:
        ratio = amount / revenue * 100
        return f"💡[요점] 계약금액 {amount_label} · 비교기준 매출액 · 비율 {ratio:.1f}%"

    mcap = _dart_market_cap_eok(stock_code)
    if mcap and mcap > 0:
        ratio = amount / mcap * 100
        return f"💡[요점] 계약금액 {amount_label} · 비교기준 시가총액(매출액 미확인) · 비율 {ratio:.1f}%"

    return f"💡[요점] 계약금액 {amount_label} · 비교기준 없음(매출액·시총 모두 미확인)"


def _calculate_importance_100(matched_count, is_exclusive, is_breaking, is_feature,
                                has_listed_company, ratio_pct=None, novelty="신규"):
    """중요도를 100점 만점으로 환산하고, 등급(이모지+글자)을 같이 반환."""
    score = 10
    score += min(matched_count, 5) * 4
    if has_listed_company:
        score += 15
    if is_exclusive:
        score += 15
    if is_breaking:
        score += 15
    if is_feature:
        score += 15
    if ratio_pct is not None:
        if ratio_pct >= 30:
            score += 20
        elif ratio_pct >= 15:
            score += 15
        elif ratio_pct >= 5:
            score += 10
        else:
            score += 5
    if novelty == "후속":
        # 🔥 후속 기사는 완전히 새로운 소식이 아니라 "이미 알려진 사건의 갱신"이라,
        # 신규 대비 살짝 낮게 책정 (그래도 새 숫자/정보가 있으니 여전히 유의미하게 높음)
        score -= 8
    score = max(1, min(score, 100))

    if score >= 90:
        grade = "S"
    elif score >= 80:
        grade = "A+"
    elif score >= 70:
        grade = "A"
    elif score >= 55:
        grade = "B"
    elif score >= 40:
        grade = "C"
    else:
        grade = "D"
    return score, grade


def classify_and_score(title):
    upper_hits = {kw for kw in STRONG_KEYWORDS_1 if kw in title}
    lower_hits = {kw for kw in STRONG_KEYWORDS_2 if kw in title}
    target_hits = {kw for kw in UNIQUE_TARGET if kw.lower() in title.lower()}
    listed_company_hits = resolve_companies_in_text(title) - NOISY_LISTED_COMPANY_NAMES

    # 상장사명이 제목에 있으면 "상위" 조건으로 인정 (KEYWORDS_1의 30여 개 대기업 루트뿐 아니라
    # KRX 전체 상장사명 매칭도 포함해서, 하위(KEYWORDS_2) 이벤트 단어와 결합되면 전송됨)
    upper_hits = upper_hits | listed_company_hits

    matched_count = len(upper_hits | lower_hits | target_hits)

    is_exclusive = any(kw in title for kw in UNIQUE_EXCLUSIVE)
    is_breaking = "속보" in title
    is_feature = "특징주" in title

    is_strong_signal = bool(upper_hits) and bool(lower_hits)  # ✏️[복구] 다시 AND로 (2개 키워드 다 필요)
    # 🎯 상장 종목명이 제목에 있으면, 다른 이벤트 단어(계약/실적 등)가 없어도
    # 그 자체로 무조건 전송 (예전에는 이벤트 단어가 같이 있어야만 전송됐음)
    has_listed_company = bool(listed_company_hits)
    should_send = is_strong_signal or has_listed_company or is_exclusive or is_breaking or is_feature

    return matched_count, is_exclusive, is_breaking, is_feature, should_send


def classify_telegram_channel_message(title):
    """
    외부 텔레그램 채널(트럼프/시황 채널 등) 전용 분류.

    일반 뉴스보다 조건을 완화해서 아래 중 하나만 걸려도 통과:
      - 중요인물 언급 (트럼프, 파월, 젠슨 황 등)
      - 글로벌 대형주 언급 (엔비디아, 테슬라 등)
      - 미국시황/매크로 단어 언급 (나스닥, 금리, 관세, 연준 등)
      - TARGET_KEYWORDS(티커/매크로) 언급
      - 기존 국내 뉴스용 상위+하위 AND 조건
      - 단독/속보/특징주 태그

    다만 "일요일 영어 공부" 같은 완전 무관한 잡담은 위 카테고리 중 아무것도
    안 걸리므로 여전히 걸러집니다 - 예전 '무필터' 상태보다는 확실히 강화된 조건.
    """
    upper_hits = {kw for kw in STRONG_KEYWORDS_1 if kw in title}
    lower_hits = {kw for kw in STRONG_KEYWORDS_2 if kw in title}
    target_hits = {kw for kw in UNIQUE_TARGET if kw.lower() in title.lower()}
    celeb_hits = {kw for kw in UNIQUE_CELEBS if kw in title}
    global_company_hits = {kw for kw in GLOBAL_COMPANY_KEYWORDS if kw in title}
    us_market_hits = {kw for kw in US_MARKET_KEYWORDS if kw in title}
    listed_company_hits = resolve_companies_in_text(title) - NOISY_LISTED_COMPANY_NAMES
    upper_hits = upper_hits | listed_company_hits

    matched_count = len(upper_hits | lower_hits | target_hits | celeb_hits | global_company_hits | us_market_hits)

    is_exclusive = any(kw in title for kw in UNIQUE_EXCLUSIVE)
    is_breaking = "속보" in title
    is_feature = "특징주" in title

    is_strong_signal = bool(upper_hits) and bool(lower_hits)  # ✏️[복구] 다시 AND로
    has_important_topic = bool(celeb_hits) or bool(global_company_hits) or bool(target_hits) or bool(us_market_hits)
    # 🎯 상장 종목명이 제목에 있으면 그 자체로 무조건 전송
    has_listed_company = bool(listed_company_hits)

    should_send = is_strong_signal or has_listed_company or has_important_topic or is_exclusive or is_breaking or is_feature

    return matched_count, is_exclusive, is_breaking, is_feature, should_send



_og_image_cache = {}


def _extract_og_image(article_url, timeout=8):
    """기사 페이지에서 대표 이미지(og:image, 없으면 twitter:image) 주소를 찾아서 반환.
    못 찾거나 오류가 나면 None. 같은 URL을 여러 번 조회하지 않도록 간단히 캐싱.

    ⚠️ 왜 필요한가: 텔레그램의 자동 링크 미리보기는 텔레그램 서버가 그 사이트에
    직접 접속해서 메타태그를 읽어오는 방식인데, 일부 언론사 사이트는 텔레그램 봇의
    접근을 막아두거나 og:image 자체를 안 넣어둬서 미리보기가 안 뜨는 경우가 있음
    (같은 사이트라도 기사마다 결과가 다르게 나오는 것도 이 때문). 그래서 우리가
    직접 기사 페이지를 읽어서 이미지 주소를 찾아 sendPhoto로 확실하게 붙이는 방식으로
    이 문제를 코드 쪽에서 통제 가능하게 만듦.
    """
    if article_url in _og_image_cache:
        return _og_image_cache[article_url]

    image_url = None
    try:
        res = requests.get(
            article_url,
            headers={"User-Agent": USER_AGENT},
            timeout=timeout,
        )
        if res.status_code == 200:
            soup = BeautifulSoup(res.text, "html.parser")
            for selector in (
                {"property": "og:image"},
                {"property": "og:image:secure_url"},
                {"name": "twitter:image"},
            ):
                tag = soup.find("meta", attrs=selector)
                if tag and tag.get("content"):
                    candidate = tag["content"].strip()
                    if candidate.startswith("//"):
                        candidate = "https:" + candidate
                    if candidate.startswith("http"):
                        image_url = candidate
                        break
    except Exception:
        image_url = None

    _og_image_cache[article_url] = image_url  # 실패(None)도 캐싱해서 같은 URL 재시도 안 함
    return image_url


def _resolve_tag(title, is_schedule, is_rumor, is_disclosure, is_exclusive, is_breaking,
                  is_feature, is_us_market, is_money, custom_source, source_label):
    """
    🔢 태그 우선순위 1~11번 표. 숫자가 작을수록 먼저 검사되고, 맨 처음 조건에
    맞는 게 채택됩니다 (일정 > 조회공시 > 전자공시 > 단독 > 속보 > 특징주 >
    해외시황 > 돈관련 > 커스텀소스 > RSS출처 > 기본).

    ⚠️ 예전엔 이 우선순위를 tag_line용 if/elif와 source_bracket용 if/elif,
    이렇게 완전히 똑같은 순서를 두 벌 따로 타고 있었습니다. 하나 고치면
    다른 쪽도 손으로 맞춰야 했고, 깜빡하면 둘이 어긋나는 버그가 생기기
    쉬운 구조였습니다. 이제 한 번의 판단으로 tag_line(공시류 메시지에 씀)과
    (source_emoji, source_bracket)(일반 뉴스 메시지에 씀)을 동시에 반환해서,
    구조적으로 절대 어긋날 수 없게 만들었습니다.

    ✏️ 태그 우선순위를 바꾸고 싶으면: 아래 번호가 매겨진 줄들의 "순서"를
    바꾸면 됩니다 (숫자가 작을수록 강한 우선순위). 문구만 바꾸고 싶으면
    해당 번호 줄의 텍스트만 고치면 됩니다.

    반환값: (tag_line, source_emoji, source_bracket)
    """
    if is_schedule:
        return "⏰ 일정", "⏰", "일정"                                              # 1순위: 일정
    if is_rumor:
        return "👀 조회공시(풍문)", "👀", "조회공시(풍문)"                            # 2순위: 조회공시(풍문)
    if is_disclosure:
        return "✅ 전자공시", "✅", "전자공시"                                       # 3순위: 전자공시
    if is_exclusive:
        return "🔥 [단독]", "🔥", "단독"                                           # 4순위: 단독
    if is_breaking:
        return "🚨[속보]🚀", "🚨", "속보🚀"                                        # 5순위: 속보
    if is_feature:
        suffix = "특징주_해외" if is_us_market else "특징주"
        return f"🚨[{suffix}]", "🚨", suffix                                      # 6순위: 특징주
    if is_us_market:
        return "🇺🇸 해외_외신", "🇺🇸", "해외_외신"                                    # 7순위: 해외
    if is_money:
        if "금리" in title:
            label = "금리"
        elif "실적" in title or "어닝서프라이즈" in title or "어닝쇼크" in title:
            label = "실적"
        else:
            label = "머니"
        return f"💰 {label}", "💰", label                                        # 8순위: 돈관련
    if custom_source:
        bracket = re.sub(r"[\[\]]", "", re.sub(r"^[^\w\uAC00-\uD7A3]+", "", custom_source)).strip()
        return custom_source, "✅", bracket                                       # 9순위: 커스텀소스(전자신문/약업신문)
    if source_label:
        return f"✅ {source_label}", "✅", source_label                           # 10순위: RSS 출처
    return "📌 [키워드]", "📌", "키워드"                                            # 11순위: 기본값


def send_telegram_message(title, news_url, time_str, matched_count, is_exclusive, is_breaking,
                         is_feature, is_us_market, is_disclosure=False, is_rumor=False,
                         custom_source="", source_label="", highlight_suffix="",
                         show_link_below=False, image_url="", novelty="신규", novelty_note=None,
                         related_theme=None, earnings_info=None, target_chat_id=None):
    # 🌏 별도 채팅방(예: 해외전용)으로 보내고 싶으면 target_chat_id를 지정.
    # 안 넘기면 기존처럼 메인 CHAT_ID로 감 - 다른 호출부는 전혀 안 바뀜.
    target_chat_id = target_chat_id or CHAT_ID

    # 🔒 링크가 http(비보안)로 넘어오면 https로 자동 승격. 텔레그램은 http 링크에
    # (버튼이든 텍스트든) "이 링크를 열까요?" 보안 확인창을 띄우는 경우가 있어서,
    # 여기서 한 번 더 안전하게 막아줌 - 소스 목록에 또 http가 실수로 들어가도
    # 이 방어선에서 자동으로 고쳐짐.
    if news_url and news_url.startswith("http://"):
        news_url = "https://" + news_url[len("http://"):]

    display_title = format_title(title)

    is_schedule = "일정" in title
    is_money = (
        "실적" in title
        or "금리" in title
        or any(kw in title for kw in MONEY_STRONG_WORDS)
    )

    tag_line, source_emoji, source_bracket = _resolve_tag(
        title, is_schedule, is_rumor, is_disclosure, is_exclusive, is_breaking,
        is_feature, is_us_market, is_money, custom_source, source_label,
    )

    is_us_related = is_us_market or any(kw.lower() in title.lower() for kw in US_CONTENT_KEYWORDS)
    is_pharma_related = any(kw in title for kw in PHARMA_KEYWORDS)

    # 🚨 중요도 점수(1~10 등급) - 모든 신호를 점수로 환산해서 합산 후 1~10 사이로 자름.
    # 1~10을 고르게 다 쓰도록 등급 기준을 명확히 정함:
    #   기본 1점
    #   + 매칭 키워드 1개당 +1점 (최대 +4점 = 키워드 4개 이상이면 만점 기여)
    #   + 단독/속보/특징주 태그 1개당 +2점 (여러 개 겹치면 그만큼 누적, 최대 +6점)
    #   + DART 공시 비율: 5% 미만 +1 / 5~15% +2 / 15~30% +3 / 30~50% +4 / 50%↑ 또는 "조원" 단위 +5
    #   + DART인데 비율 없이 확실한 이벤트(흑자전환 등)면 +2
    # 이론상 최대 1+4+6+5=16이 나올 수 있지만 10에서 잘라내서, 정말 여러 신호가
    # 한꺼번에 겹치는 "찐" 이벤트만 10등급을 받도록 함.
    importance_score = 1
    importance_score += min(matched_count, 4)
    if is_exclusive:
        importance_score += 2
    if is_breaking:
        importance_score += 2
    if is_feature:
        importance_score += 2
    if is_disclosure and highlight_suffix:
        pct_match = re.findall(r"(\d+(?:\.\d+)?)\s*%", highlight_suffix)
        if pct_match:
            pct = max(float(p) for p in pct_match)  # 여러 줄이면 그중 가장 큰 비율 기준
            if pct >= 50 or "조원" in highlight_suffix:
                importance_score += 5
            elif pct >= 30:
                importance_score += 4
            elif pct >= 15:
                importance_score += 3
            elif pct >= 5:
                importance_score += 2
            else:
                importance_score += 1
        else:
            importance_score += 5  # 흑자전환처럼 %는 없지만 확실한(=최고등급) 이벤트
    importance_score = max(1, min(importance_score, 10))

    # 🚀💯🚀 "이건 상한가 재료급이다" 싶은 특정 조합 - 5점 기준과 별개로,
    # 아래 5가지 조합 중 하나라도 해당하면 최상위 표시로 따로 구분함.
    #  ① (상장기업 또는 유명인) + "세계최초" + 다른 키워드2 하나 더
    #  ② 유명인 + 유명기업(글로벌 대기업 포함) + 키워드1(상위) + 키워드2(하위)
    #  ③ M&A/합병 계열 단어 + 상장기업명 + 다른 신호(키워드 2개 이상 겹침)
    #  ④ FDA/임상 계열 단어 + 상장기업명 + 다른 신호(키워드 2개 이상 겹침)
    #  ⑤ 흑자전환 (DART 공시 - highlight_suffix에 "흑자전환" 포함)
    has_listed_company_here = any(name in title for name in ALL_LISTED_COMPANIES)
    has_celeb_here = any(c in title for c in UNIQUE_CELEBS)
    has_global_company_here = any(g in title for g in UNIQUE_GIANTS)
    lower_hits_here = {kw for kw in STRONG_KEYWORDS_2 if kw in title}
    upper_hits_here = {kw for kw in STRONG_KEYWORDS_1 if kw in title}

    MEGA_MA_WORDS = {"합병", "인수", "M&A", "M&A타진", "경영권분쟁", "흡수합병", "분할합병", "인수합병"}
    MEGA_FDA_WORDS = {"美FDA", "미FDA", "FDA", "임상3상", "임상2상", "임상1상", "임상시험", "품목허가", "美FDA임상"}

    is_mega_combo = False
    if (has_listed_company_here or has_celeb_here) and "세계최초" in title and (lower_hits_here - {"세계최초"}):
        is_mega_combo = True
    elif has_celeb_here and has_global_company_here and upper_hits_here and lower_hits_here:
        is_mega_combo = True
    elif any(w in title for w in MEGA_MA_WORDS) and has_listed_company_here and matched_count >= 2:
        is_mega_combo = True
    elif any(w in title for w in MEGA_FDA_WORDS) and has_listed_company_here and matched_count >= 2:
        is_mega_combo = True
    elif is_disclosure and highlight_suffix and "흑자전환" in highlight_suffix:
        is_mega_combo = True

    # ⏸️ [2026-08-13 임시 비활성화] 속보/단독 등을 이모지로 강조하던 아래 로직은
    # 이제 100점 중요도 점수/등급(🧮→📌 중요도 XX/100)이 같은 역할을 하므로
    # 일단 꺼둡니다. is_mega_combo 등 판단 자체는 그대로 계산해두되(나중에
    # 다시 켜고 싶을 때를 위해 로직은 안 지움), title_prefix에는 반영하지 않음.
    title_prefix = ""
    # title_prefix = "📌"
    # if is_mega_combo:
    #     title_prefix = "🚀💯"  # 위 5가지 조합 중 하나에 해당하는 최상위 재료
    # elif importance_score >= 5:
    #     title_prefix = "🚀"  # 중요도 5점 이상이면 다른 이모지 안 섞고 이것만 단독 표시
    # if is_us_related:
    #     title_prefix = "🇺🇸" + title_prefix
    # if is_pharma_related:
    #     title_prefix = title_prefix + "💊"


    # 시가총액대비/매출액대비/전년비 등 근거를 제목 밑에 그대로 이어붙임
    # (📊비교대상/🚨비율/💰금액 라벨은 dart 쪽에서 이미 붙여서 넘어옴)
    highlight_line = ""
    if highlight_suffix:
        escaped = html.escape(highlight_suffix)
        # 🎯괴리율 줄만 콕 집어서 밑줄 처리 (다른 줄은 그대로)
        escaped = re.sub(r"(🎯괴리율[^\n]*)", r"<u>\1</u>", escaped)
        highlight_line = f"\n{escaped}"


    # 🧮 100점 만점 중요도 점수 + [요점] 한 줄 (계약금액 매출대비 비율 등)
    has_listed_company_for_score = bool(resolve_companies_in_text(title))
    key_point_line = _build_key_point_line(title, is_disclosure, highlight_suffix)
    ratio_pct_candidates = []
    if key_point_line:
        pct_match = re.search(r"(\d+(?:\.\d+)?)\s*%", key_point_line)
        if pct_match:
            ratio_pct_candidates.append(float(pct_match.group(1)))
    # 🐛[버그 수정] 매출/영업이익/순이익 증감률(highlight_suffix 안의 재무실적
    # 카드)이 지금까지 중요도 점수 계산에 전혀 반영이 안 되고 있었음 - 순이익이
    # 50% 늘어도 점수가 낮게 나오던 원인. 재무실적 줄에 있는 증감률 중 가장 큰
    # 걸 [요점] 비율과 같이 후보에 넣어서, 둘 중 더 강한 신호를 점수에 씀.
    if is_disclosure and highlight_suffix:
        for m in re.finditer(r"🔺(\d+(?:\.\d+)?)%|▼(\d+(?:\.\d+)?)%", highlight_suffix):
            val = float(m.group(1) or m.group(2))
            ratio_pct_candidates.append(val)
    ratio_pct_for_score = max(ratio_pct_candidates) if ratio_pct_candidates else None
    score100, grade100 = _calculate_importance_100(
        matched_count, is_exclusive, is_breaking, is_feature,
        has_listed_company_for_score, ratio_pct_for_score, novelty,
    )
    score_line = f"✔️ 중요도 {score100} / 100\n✔️ 등급 {grade100}"

    # 🆕 신규/후속 표시 줄 (재탕은 애초에 여기까지 안 오고 발송 직전에 걸러짐)
    if novelty == "후속":
        novelty_line = f"✔️ [후속] {novelty_note}\n" if novelty_note else "✔️ [후속]\n"
    else:
        novelty_line = "✔️ [신규]\n"

    # 🔗 이 뉴스가 특정 테마(반도체/2차전지 등)와 관련 있으면, 그 테마의 국내
    # 관련주를 바로 붙여줌 (해외뉴스 하나하나에도 "그래서 국내에서 뭘 봐야
    # 하지?"를 바로 답해주기 위함 - 아침 브리핑에서만 쓰던 로직을 재사용)
    related_theme_line = ""
    if related_theme:
        stocks_str = ", ".join(related_theme["kr_stocks"])
        related_theme_line = f"✔️ 관련 국내 테마주 [{related_theme['name']}]: {stocks_str}\n"

    # 📊 실적발표(어닝) 표시 - beat/miss와 매출·EPS는 제목에 직접 숫자가 있을 때만
    # 채워짐(본문을 안 읽으므로). 없으면 "실적발표"라는 사실만 표시.
    earnings_line = ""
    if earnings_info:
        is_earnings, beat_or_miss, revenue, eps = earnings_info
        if is_earnings:
            beat_label = {"beat": "📈 예상 상회(beat)", "miss": "📉 예상 하회(miss)"}.get(beat_or_miss, "확인필요")
            parts = [f"실적발표 - {beat_label}"]
            if revenue:
                parts.append(f"매출 {revenue}")
            if eps:
                parts.append(f"EPS {eps}")
            earnings_line = f"✔️ {' · '.join(parts)}\n"

    key_point_html = html.escape(key_point_line) + "\n" if key_point_line else ""

    if is_disclosure or is_rumor:
        # 📋 DART 공시류 - 구분선 없이 빈 줄로만 섹션을 나눔:
        # 🚀 태그 🏢⚡️회사명(시총)   ⏰시간 / (빈줄) / 👀실적유형(굵게) / (빈줄) / 본문(괴리율·PER·EPS·매출등) / (빈줄) / 🔗링크
        # (display_title은 이미 맨 위에서 format_title()로 한 번 포맷팅된 HTML이라
        #  여기서 또 escape/format하면 이중 처리가 되어 태그가 깨짐 - 그대로 잘라서만 씀)
        corp_header, _, report_body = display_title.partition("\n")
        body_escaped = ""
        if highlight_suffix:
            body_escaped = html.escape(highlight_suffix)
            body_escaped = re.sub(r"(🎯괴리율[^\n]*)", r"<u>\1</u>", body_escaped)
        body_section = f"{body_escaped}\n\n" if body_escaped else ""
        header_line_prefix = f"{title_prefix} " if title_prefix else ""
        text_content = (
            f"{header_line_prefix}{tag_line} {corp_header}          <i>⏰ {time_str}</i>\n\n"
            f"<b>{report_body}</b>\n\n"
            f"{novelty_line}"
            f"{key_point_html}"
            f"{score_line}\n\n"
            f"{body_section}"
        )
        # 🔘 링크를 텍스트(<a>)가 아니라 버튼(인라인 키보드)으로 바꿈.
        # ⚠️ 텔레그램은 "표시 글자와 실제 주소가 다른 텍스트 링크"는 전부
        # (글자가 URL처럼 안 생겼어도) "이 링크를 열까요?" 확인창을 띄웁니다.
        # 반면 버튼은 눌렀을 때 확인창 없이 바로 열립니다 - 그래서 링크를
        # 아예 버튼으로 빼서 확인창 자체가 안 뜨게 함.
        reply_markup = (
            {"inline_keyboard": [[{"text": "🔗 원문보기", "url": news_url}]]} if news_url else None
        )
    else:
        # 📰 일반 뉴스(RSS/네이버/텔레그램 등):
        # 📌[출처] · ⏰시간 / (빈줄) / 제목 / (빈줄) / 🔘기사보기(버튼)
        #
        # ⚠️ 텔레그램은 "표시 글자와 실제 주소가 다른 텍스트 링크"는 전부(글자가
        # URL처럼 안 생겼어도) "이 링크를 열까요?" 확인창을 띄웁니다. 그래서
        # 링크를 텍스트에서 아예 빼고 버튼(인라인 키보드)으로 옮겼습니다 -
        # 버튼은 눌렀을 때 확인창 없이 바로 열립니다.
        # 🖼️ 그림 미리보기는 텍스트 안에 링크가 없어도, link_preview_options의
        # "url" 필드로 따로 지정할 수 있어서 이 방식으로도 그대로 유지됩니다.
        # (source_bracket은 위에서 tag_line과 같은 우선순위로 이미 순수 텍스트로 계산해둠)

        # 🏢 요청에 따라: 제목에서 상장기업명이 매칭되고, 그 회사의 종목코드를
        # 알고 있으면(KRX 목록에서 조회 가능하면) DART 실적카드와 같은 방식으로
        # 시가총액/괴리율/PER·EPS·ROE를 붙여줌 - "출처가 확실한" 일반 뉴스도
        # 공시처럼 바로 참고할 기업분석 정보가 같이 오도록.
        company_snapshot_line = ""
        matched_company, stock_code = resolve_primary_company(title)

        # ⏰ 특징주로 뜬 종목은 워치리스트에 등록 (나중에 DART에서 이 종목의
        # 미래 일정이 나오면 리마인더로 알려주기 위함)
        if is_feature and matched_company:
            _add_to_watchlist(matched_company, "특징주")

        if matched_company:
            if stock_code:
                mcap = _dart_market_cap_eok(stock_code)
                snap_parts = [x for x in (
                    _dart_gap_ratio_label(stock_code),
                    _dart_valuation_line(stock_code),
                ) if x]
                # 🏦 재무점수 (매출성장/영업이익성장/영업이익률/ROE/부채비율/영업현금흐름 100점)
                fin_snap = _dart_financial_snapshot(stock_code)
                fin_score, fin_grade, fin_missing = calculate_financial_score_100(fin_snap)
                if fin_snap:  # 재무제표 자체를 못 가져온 경우(신규상장 등)는 아예 표시 안 함
                    fin_line = f"✔️ 재무점수 {fin_score} / 100\n✔️ 등급 {fin_grade}"
                    if fin_missing:
                        fin_line += f" (참고: {'/'.join(fin_missing)} 데이터 없음)"
                    snap_parts.append(fin_line)
                header_bits = [f"🏢{matched_company}"]
                if mcap:
                    header_bits.append(f"(시가총액 {_eok_comma_label(mcap)})")
                lines = [" ".join(header_bits)] + snap_parts
                company_snapshot_line = "\n" + "\n".join(lines) + "\n"

        # 🚀/💊/🇺🇸 같은 특수 표시가 없는 기본값(📌)이면 헤더에서 아예 생략함
        # (어차피 제목 앞에도 📌가 따로 붙어서, 헤더에 또 있으면 중복이라 지저분함)
        header_prefix = "" if title_prefix == "📌" else title_prefix
        text_content = (
            f"{header_prefix}{source_emoji}[{source_bracket}]                    <i>⏰ {time_str}</i>\n\n"
            f"📌<b>{display_title}</b>{highlight_line}\n\n"
            f"{novelty_line}"
            f"{related_theme_line}"
            f"{earnings_line}"
            f"{key_point_html}"
            f"{score_line}\n"
            f"{company_snapshot_line}"
        )
        reply_markup = (
            {"inline_keyboard": [[{"text": "🔗 기사보기", "url": news_url}]]} if news_url else None
        )

    # 🖼️ 이미지 주소가 있으면(예: 전자신문/약업신문에서 직접 추출한 og:image) sendPhoto로
    # 확실하게 사진을 첨부해서 보냄 - 텔레그램의 자동 미리보기(사이트가 봇 접근을
    # 막아두면 실패)에 의존하지 않아서 훨씬 안정적으로 그림이 뜸.
    # (DART 공시/조회공시는 원래 미리보기 없이 깔끔하게 유지하는 정책이라 이미지 첨부 제외.
    #  캡션은 텔레그램 제한상 1024자를 넘으면 sendPhoto가 거부하므로 그 경우도 일반 방식으로.)
    use_photo = bool(image_url) and not (is_disclosure or is_rumor) and len(text_content) <= 1024

    def _build_request(as_photo):
        endpoint = "sendPhoto" if as_photo else "sendMessage"
        req_url = f"https://api.telegram.org/bot{BOT_TOKEN}/{endpoint}"
        if as_photo:
            req_payload = {
                "chat_id": target_chat_id,
                "photo": image_url,
                "caption": text_content,
                "parse_mode": "HTML",
            }
        else:
            req_payload = {
                "chat_id": target_chat_id,
                "text": text_content,
                "parse_mode": "HTML",
            }
            if is_disclosure or is_rumor:
                # 📋 DART 공시는 이미 정보가 많아서, 미리보기 이미지 없이 깔끔하게 유지
                req_payload["disable_web_page_preview"] = True  # 예전 방식(하위호환용)
                req_payload["link_preview_options"] = {"is_disabled": True}  # 텔레그램 최신 방식
            else:
                # 📰 일반 뉴스는 이미지를 직접 못 구했을 때의 대체 경로 -
                # 텔레그램 자체 미리보기라도 켜서 되면 다행이고, 안 되면 그냥 텍스트만 나감.
                # ⚠️ 링크를 텍스트가 아니라 버튼으로 옮겼기 때문에("이 링크를 열까요?"
                # 확인창 방지), 미리보기 대상 URL을 "url" 필드로 명시적으로 지정해야
                # 함 - 안 그러면 텔레그램이 미리보기를 만들 링크를 텍스트에서 못 찾음.
                if news_url:
                    req_payload["link_preview_options"] = {
                        "is_disabled": False,
                        "prefer_large_media": True,
                        "url": news_url,
                    }
                else:
                    req_payload["link_preview_options"] = {"is_disabled": True}
        if reply_markup:
            req_payload["reply_markup"] = reply_markup
        return req_url, req_payload

    url, payload = _build_request(use_photo)

    # 메시지 사이 최소 간격 확보 (너무 빠르게 연속 전송하면 텔레그램이 429로 막음)
    global _last_telegram_send_ts
    elapsed = time.time() - _last_telegram_send_ts
    if elapsed < MIN_TELEGRAM_SEND_INTERVAL:
        time.sleep(MIN_TELEGRAM_SEND_INTERVAL - elapsed)

    max_attempts = 6
    for attempt in range(max_attempts):
        try:
            res = requests.post(url, json=payload, timeout=10)
            if res.status_code == 200:
                _last_telegram_send_ts = time.time()
                print(f"[텔레그램 전송 완료] {title}")
                return True

            if res.status_code == 429:
                # 텔레그램 속도제한. retry_after만큼 기다렸다가 다시 시도 (메시지를 버리지 않음)
                retry_after = 5
                try:
                    retry_after = res.json().get("parameters", {}).get("retry_after", 5)
                except Exception:
                    pass
                print(f"[텔레그램 전송 대기] 429 Too Many Requests - {retry_after}초 후 재시도 ({title})")
                time.sleep(retry_after + 1)
                continue

            print(f"[텔레그램 전송 실패] status={res.status_code} body={res.text[:200]}")

            # 🔄 sendPhoto가 실패했다면(이미지 주소가 텔레그램 기준으로 유효하지 않은 경우 등,
            # 보통 400) 이미지 없이 일반 메시지로 즉시 대체 전송을 시도함 - 이미지 하나 때문에
            # 기사 자체가 아예 안 보내지는 것을 막기 위함.
            if use_photo:
                print(f"[텔레그램 이미지 전송 실패 → 일반 메시지로 대체] {title}")
                use_photo = False
                url, payload = _build_request(False)
                continue
        except Exception as e:
            print(f"[텔레그램 전송 오류] {e}")

        if attempt < max_attempts - 1:
            time.sleep(2)

    _last_telegram_send_ts = time.time()
    print(f"[텔레그램 전송 최종 실패] {title}")
    return False


def is_recent_article(entry, minutes=60, default_if_unknown=True):
    """
    entry의 발행시각이 minutes(분) 이내인지 확인.
    default_if_unknown: 발행시각을 아예 못 읽었을 때 어떻게 할지.
      - 실시간 뉴스 RSS(국내/해외)는 대부분 날짜가 있고, 혹시 없더라도
        속보를 놓치면 안 되니 기본값 True(통과)를 유지합니다.
      - 블로그처럼 오래된 글이 섞여 들어올 위험이 큰 곳은 호출할 때
        default_if_unknown=False로 넘겨서 "모르면 제외"하도록 안전하게 씁니다.
    """
    try:
        published_parsed = getattr(entry, "published_parsed", None)
        if published_parsed:
            article_time = datetime.datetime.fromtimestamp(time.mktime(published_parsed))
        else:
            published_str = getattr(entry, "published", "")
            if published_str:
                article_time = parsedate_to_datetime(published_str).replace(tzinfo=None)
            else:
                return default_if_unknown

        now = datetime.datetime.now()
        diff_minutes = (now - article_time).total_seconds() / 60
        return 0 <= diff_minutes <= minutes
    except Exception:
        return default_if_unknown


def fetch_krx_company_names():
    """
    KRX(한국거래소) 정보데이터시스템(KIND)에서 코스피+코스닥 상장법인 전체 명단을 받아와서
    회사명과 종목코드를 같이 추출. 실패하면 빈 값들을 반환하고 조용히 넘어감
    (이 기능 없이도 봇은 정상 작동). 종목코드는 COMPANY_NAME_TO_CODE에 채워서,
    일반 뉴스에서도 회사명만으로 시가총액/PER 등을 조회할 수 있게 함.
    """
    url = "https://kind.krx.co.kr/corpgeneral/corpList.do?method=download&searchType=13"
    try:
        res = requests.get(url, headers={"User-Agent": USER_AGENT}, timeout=15)
        res.encoding = "euc-kr"
        soup = BeautifulSoup(res.text, "html.parser")
        table = soup.find("table")
        if not table:
            print("⚠️ KRX 상장법인 목록: 표를 찾지 못했습니다. (사이트 구조가 바뀌었을 수 있음)")
            return set(), {}

        names = set()
        name_to_code = {}
        rows = table.find_all("tr")[1:]  # 첫 행은 헤더(회사명, 종목코드, 업종...)
        for row in rows:
            cells = row.find_all("td")
            if not cells:
                continue
            name = cells[0].get_text(strip=True)
            # 너무 짧은 이름(1글자)은 오매칭 위험이 커서 제외
            if name and len(name) >= 2:
                names.add(name)
                if len(cells) >= 2:
                    code = cells[1].get_text(strip=True)
                    if re.fullmatch(r"\d{6}", code):
                        name_to_code[name] = code
        return names, name_to_code
    except Exception as e:
        print(f"⚠️ KRX 상장법인 목록을 가져오지 못했습니다: {e}")
        return set(), {}


def initialize_existing_rss():
    print("🧹 [초기화] 기존에 쌓여 있던 오래된 뉴스 목록을 정리 중입니다...")
    feedparser.USER_AGENT = USER_AGENT
    all_urls = (
        DOMESTIC_RSS_URLS
        + US_RSS_URLS
        + [url for _, url in ANALYSIS_BLOG_RSS_URLS]
        + [url for _, url in YOUTUBE_CHANNEL_RSS_URLS]
    )
    for rss_url in all_urls:
        try:
            feed = _fetch_rss_feed(rss_url)
            for entry in feed.entries:
                title = getattr(entry, "title", "")
                if title:
                    mark_as_sent(title)
        except Exception:
            continue
    print("✅ [초기화 완료] 현재 기준 이전 기사 필터링 등록 완료.")


def initialize_existing_telegram_channels():
    """
    텔레그램1(필터)+텔레그램2(무조건) 채널에 지금 이미 올라와 있는 글들을 미리
    sent_news_titles에 등록. 이걸 안 하면 봇을 켤 때마다 채널의 최근 게시물이
    전부 "새 글"로 인식돼서 한꺼번에 쏟아지게 됨.
    """
    headers = {"User-Agent": USER_AGENT}
    all_channels = TARGET_TELEGRAM_CHANNELS + TARGET_TELEGRAM_CHANNELS_UNFILTERED
    registered = 0
    for channel_name, channel_url in all_channels:
        try:
            res = requests.get(channel_url, headers=headers, timeout=10)
            if res.status_code != 200:
                continue
            soup = BeautifulSoup(res.text, "html.parser")
            messages = soup.select(".tgme_widget_message_text")
            for msg in messages:
                headline, _, _ = extract_telegram_headline_and_link(msg, channel_url)
                if headline:
                    mark_as_sent(headline)
                    registered += 1
        except Exception as e:
            print(f"[텔레그램 초기화 오류] ({channel_name}): {e}")
            continue
    print(f"✅ [초기화] 텔레그램 채널 {len(all_channels)}개의 기존 게시물 {registered}건 등록 완료.")


def initialize_existing_custom_sources():
    """약업신문/전자신문도 지금 걸려있는 기사들을 미리 등록 (위와 같은 이유).
    ⚠️ check_custom_sources()와 반드시 동일한 제목 추출 로직(_extract_custom_source_headline)을
    써야 함 - 다르면 등록이 무용지물이 되어 재시작할 때마다 기존 기사가 전부
    "새 기사"로 쏟아지는 버그가 남(과거에 실제로 이 버그가 있었음)."""
    headers = {"User-Agent": USER_AGENT}
    registered = 0
    for target_url, source_name in CUSTOM_SCRAPE_SOURCES:
        try:
            res = requests.get(target_url, headers=headers, timeout=10)
            if res.status_code != 200:
                continue
            soup = BeautifulSoup(res.text, "html.parser")
            for a_tag in soup.select("a"):
                title = _extract_custom_source_headline(a_tag)
                if title and len(title) > 4:
                    mark_as_sent(title)
                    registered += 1
        except Exception as e:
            print(f"[커스텀소스 초기화 오류] ({source_name}): {e}")
            continue
    print(f"✅ [초기화] 약업신문/전자신문 기존 기사 {registered}건 등록 완료.")


# ============================================================
# 국내 뉴스 체크
# ============================================================
def _fetch_rss_feed(rss_url, timeout=10):
    """
    RSS를 안정적으로 가져와서 파싱한다. feedparser가 URL을 직접 받아서 자체
    fetch하면(과거 방식) 인코딩 선언 불일치("declared as us-ascii, but parsed
    as utf-8")나 일부 서버의 리다이렉트/압축 처리 문제로 파싱이 깨지는 경우가
    있어서, requests로 먼저 제대로 가져온 뒤(res.content, 원본 바이트) 그걸
    feedparser에 넘기는 방식이 훨씬 안정적이다. 그래도 실패하면 feedparser의
    자체 fetch로 한 번 더 시도(완전히 포기하지 않음).
    """
    try:
        res = requests.get(rss_url, headers={"User-Agent": USER_AGENT}, timeout=timeout)
        if res.status_code == 200:
            return feedparser.parse(res.content)
    except Exception as e:
        print(f"[RSS 요청 오류] {rss_url}: {e}")
    # 위에서 실패했으면 feedparser 자체 fetch로 마지막 시도
    return feedparser.parse(rss_url)


def check_domestic_news(current_time_str):
    feedparser.USER_AGENT = USER_AGENT
    scanned = 0
    sent = 0
    diag_counts = {"raw": 0, "already_sent": 0, "blocked": 0, "too_old": 0}
    for rss_url in DOMESTIC_RSS_URLS:
        try:
            feed = _fetch_rss_feed(rss_url)
        except Exception as e:
            print(f"[국내 RSS 오류] {rss_url}: {e}")
            continue

        diag_counts["raw"] += len(feed.entries)
        if getattr(feed, "bozo", False):
            print(f"[국내 RSS 파싱경고] {rss_url}: {getattr(feed, 'bozo_exception', '알 수 없음')}")

        source_label = DOMESTIC_RSS_SOURCE_NAMES.get(rss_url, "")
        if not source_label:
            try:
                source_label = urlparse(rss_url).netloc.replace("www.", "")
            except Exception:
                source_label = "뉴스"

        for entry in feed.entries:
            title = getattr(entry, "title", "")
            link = getattr(entry, "link", "")
            if not title:
                continue
            if is_already_sent(title):
                diag_counts["already_sent"] += 1
                continue
            if is_blocked_title(title):  # 🧹 삭제어 포함 시 무조건 차단
                diag_counts["blocked"] += 1
                mark_as_sent(title)
                continue
            if not is_recent_article(entry):
                diag_counts["too_old"] += 1
                continue

            scanned += 1
            matched_count, is_exclusive, is_breaking, is_feature, should_send = classify_and_score(title)

            if not should_send:
                mark_as_sent(title)
                continue

            # 🆕 문자 그대로는 안 겹치지만 사실상 같은 기사(다른 매체가 다른 문구로
            # 쓴 경우 등)면 여기서 신규/후속/재탕을 구분함. 재탕(새 정보 없음)만
            # 걸러내고, 후속(새 숫자/정보 있음)은 표시를 붙여서 그대로 보냄.
            novelty, novelty_emoji, novelty_note = classify_novelty(title)
            if novelty == "재탕":
                print(f"[재탕 감지] {title[:60]}")
                mark_as_sent(title)
                continue

            # 🚫 먼저 "전송 예정"으로 등록해서, 같은 뉴스가 다른 소스(RSS/네이버 등)에서
            # 거의 동시에 잡혀도 절대 두 번 나가지 않게 함.
            mark_as_sent(title)
            _remember_for_fuzzy(title)
            send_telegram_message(
                title, link, current_time_str, matched_count,
                is_exclusive, is_breaking, is_feature, False,
                source_label=source_label,
                novelty=novelty, novelty_note=novelty_note,
            )
            sent += 1

    print(f"[{current_time_str}] 국내 RSS: 최근 1시간 이내 신규 {scanned}건 확인, {sent}건 전송 "
          f"(원본{diag_counts['raw']}건 / 이미본것{diag_counts['already_sent']} / 삭제어{diag_counts['blocked']} / "
          f"오래됨{diag_counts['too_old']})")


# ============================================================
# 해외(미국장) 뉴스 체크
# ============================================================
# ============================================================
# 🌅 아침 브리핑 (해외 지수/종목 시세 → 오늘의 테마 → 국내 관련주)
# ============================================================
_yahoo_quote_cache = {}


def _fetch_yahoo_quote(symbol):
    """
    야후 파이낸스 비공식 API로 현재가/등락률을 가져온다. API키 불필요.
    실패하면 (None, None). 5분 캐시 (아침 브리핑은 하루 한 번만 쓰지만,
    혹시 재시도되는 경우를 대비해 짧게라도 캐싱).
    """
    now = time.time()
    cached = _yahoo_quote_cache.get(symbol)
    if cached and now - cached[2] < 300:
        return cached[0], cached[1]

    price, change_pct = None, None
    try:
        res = requests.get(
            f"https://query1.finance.yahoo.com/v8/finance/chart/{symbol}",
            headers={"User-Agent": USER_AGENT},
            params={"range": "1d", "interval": "5m"},
            timeout=8,
        )
        data = res.json()
        result = data.get("chart", {}).get("result")
        if result:
            meta = result[0].get("meta", {})
            price = meta.get("regularMarketPrice")
            prev_close = meta.get("previousClose") or meta.get("chartPreviousClose")
            if price is not None and prev_close:
                change_pct = (price - prev_close) / prev_close * 100
    except Exception as e:
        print(f"[야후 시세 조회 오류] {symbol}: {e}")

    _yahoo_quote_cache[symbol] = (price, change_pct, now)
    return price, change_pct


def _classify_us_themes(quote_map):
    """
    THEME_DEFINITIONS 전체를 훑어서, 조건(관련종목 중 threshold% 이상 오른 게
    min_count개 이상)을 만족하는 테마를 전부 찾고, "강도" 순으로 정렬해서 반환.
    강도 = (조건 만족 종목 수) × (그 종목들의 평균 상승률) - 단순하지만 명확한 규칙.
    반환: [(테마dict, 강도, [(종목명, 등락률), ...]), ...] 강도 내림차순
    """
    results = []
    for theme in THEME_DEFINITIONS:
        up_stocks = []
        for sym in theme["us_symbols"]:
            price, chg = quote_map.get(sym, (None, None))
            if chg is not None and chg >= theme["threshold"]:
                up_stocks.append((sym, chg))
        if len(up_stocks) >= theme["min_count"]:
            strength = len(up_stocks) * (sum(c for _, c in up_stocks) / len(up_stocks))
            results.append((theme, strength, up_stocks))
    results.sort(key=lambda x: x[1], reverse=True)
    return results


def _rank_domestic_candidates(kr_stock_names, limit=3):
    """
    국내 관련주 후보들을 "상한가 여부 → 상승률" 순으로 우선 정렬해서 대장주를
    가려낸다. 상한가에 오른 종목은 그 자체로 최우선(등락률과 무관하게 맨 위),
    그 다음은 실제 상승률이 높은 순. 상승률 정보를 못 구한 종목은 맨 뒤로
    밀리되(0으로 취급) 후보에서 아예 빠지진 않음 - 데이터 부족이 곧 "나쁘다"는
    뜻은 아니므로. 외국인수급/당일공시는 순위와 별개로 "부가 근거"로만 붙임.
    반환: [(종목명, 상한가여부, 등락률 또는 None, 근거 문장 리스트), ...]
          정렬 완료, 최대 limit개. 맨 앞이 "대장주".
    """
    upper_limit_names = _naver_upper_limit_stock_names()

    scored = []
    for name in kr_stock_names:
        stock_code = COMPANY_NAME_TO_CODE.get(name)
        is_upper_limit = name in upper_limit_names
        change_pct = None
        reasons = []

        if not stock_code:
            scored.append((name, is_upper_limit, None, ["종목코드 미확인"]))
            continue

        supply = _naver_supply_demand(stock_code)
        if supply and supply.get("change_pct") is not None:
            change_pct = supply["change_pct"]
            reasons.append(f"오늘 등락률 {change_pct:+.2f}%")
        if supply and supply.get("foreign_net") is not None:
            if supply["foreign_net"] > 0:
                reasons.append(f"외국인 순매수 {supply['foreign_net']:,}주")
            elif supply["foreign_net"] < 0:
                reasons.append(f"외국인 순매도 {abs(supply['foreign_net']):,}주")

        has_disclosure = _dart_has_disclosure_today(stock_code)
        if has_disclosure:
            reasons.append("금일 DART 공시 있음")

        if is_upper_limit:
            reasons.insert(0, "🔺상한가")
        if not reasons:
            reasons.append("현재 확인된 특이 수급/공시 없음")

        scored.append((name, is_upper_limit, change_pct, reasons))

    # 정렬 기준: ① 상한가 여부(상한가가 최우선) ② 등락률 내림차순(모르면 맨 뒤)
    scored.sort(key=lambda x: (x[1], x[2] if x[2] is not None else -999), reverse=True)
    return scored[:limit]


def build_morning_briefing_text():
    """아침 브리핑 텍스트를 조립. 지수 시세를 전부 못 가져오면 None(발송 안 함)."""
    index_lines = []
    any_index_ok = False
    for name, symbol in US_MARKET_INDICES:
        price, chg = _fetch_yahoo_quote(symbol)
        if price is None:
            index_lines.append(f"{name}  조회 실패")
            continue
        any_index_ok = True
        arrow = "🔺" if (chg or 0) >= 0 else "🔻"
        index_lines.append(f"{name}  {price:,.2f}  {arrow}{chg:+.2f}%")

    if not any_index_ok:
        print("⚠️ [아침 브리핑] 지수 시세를 전부 못 가져와서 브리핑을 건너뜁니다.")
        return None

    # 📈 US_KEY_STOCKS + 모든 테마의 관련종목을 한 번에 조회(중복 없이)
    all_symbols = sorted({sym for _, sym in US_KEY_STOCKS} | set(_THEME_ALL_SYMBOLS))
    quote_map = {}
    for sym in all_symbols:
        quote_map[sym] = _fetch_yahoo_quote(sym)

    stock_lines = []
    for name, symbol in US_KEY_STOCKS:
        price, chg = quote_map.get(symbol, (None, None))
        if price is None:
            continue
        arrow = "🔺" if (chg or 0) >= 0 else "🔻"
        stock_lines.append(f"{name}  {arrow}{chg:+.2f}%")

    ranked_themes = _classify_us_themes(quote_map)

    lines = ["🇺🇸 해외시장", ""]
    lines.extend(index_lines)
    lines.append("")
    if stock_lines:
        lines.append("⭐ 주요 종목")
        lines.extend(stock_lines)
        lines.append("")

    if not ranked_themes:
        lines.append("✔️ 오늘은 특별히 두드러진 테마 강세는 안 보입니다.")
        return "\n".join(lines)

    # 🥇 상위 3개 테마까지만 "N순위"로 표시
    top_themes = ranked_themes[:3]
    lines.append("✔️ 오늘 핵심 테마 (강도순)")
    for i, (theme, strength, up_stocks) in enumerate(top_themes, start=1):
        stock_desc = ", ".join(f"{sym}{c:+.1f}%" for sym, c in up_stocks)
        lines.append(f"{i}순위 {theme['name']}  ({stock_desc})")
    lines.append("")

    # 1순위 테마에 대해서만 서술형 이유 + 국내 연결까지 자세히
    top_theme, top_strength, top_up_stocks = top_themes[0]
    lines.append(f"✔️ 오늘 1순위: {top_theme['name']} 강세")
    lines.append("일반적 배경(참고용, 오늘자 확정 사실 아님):")
    for i, reason in enumerate(top_theme["reasons"], start=1):
        lines.append(f"  {i}. {reason}")
    lines.append("")

    lines.append("━━━━━━━━━━━━")
    lines.append("🇰🇷 오늘 국내장 영향")
    lines.append("━━━━━━━━━━━━")
    for rank, (theme, strength, up_stocks) in enumerate(top_themes, start=1):
        lines.append(f"{rank}순위 {theme['name']}")

    lines.append("")
    # 🔗 1위 테마만 보지 않고, 상위 테마들(최대 3개)의 관련종목을 전부 합쳐서
    # 그 안에서 "이미 반응 중인 종목"과 "아직 안 오른 종목"을 둘 다 봄.
    # 같은 종목이 여러 테마에 걸쳐 있으면 먼저 나온(=더 강한) 테마 이름을 씀.
    combined_candidates = []
    seen_names = set()
    name_to_theme = {}
    for theme, strength, up_stocks in top_themes:
        for name in theme["kr_stocks"]:
            if name not in seen_names:
                seen_names.add(name)
                combined_candidates.append(name)
                name_to_theme[name] = theme["name"]

    # ⚠️ 중요: 아래 두 목록은 "미래 상승 예측"이 아닙니다. 상한가/상승률이
    # 높다는 건 "이미 그만큼 올랐다"는 과거·현재 사실일 뿐이고, 이게 앞으로
    # 더 오른다는 근거는 못 됩니다(오히려 재료가 이미 반영돼서 상승 여력이
    # 줄었을 수도 있음). 진짜 "이 테마가 뜨면 다음날 어느 종목이 잘 오르더라"
    # 같은 예측력 있는 순위를 만들려면 과거 데이터(백테스트)가 필요한데,
    # 아직 그 데이터가 없어서 지금은 "오늘 이미 반응한 종목이 뭔지 확인하는
    # 용도"로만 씁니다. 그래서 아래에서 "아직 안 오른 관련주(순환매 후보)"도
    # 같이 보여줍니다 - 테마가 진짜 강하면 이런 종목이 뒤늦게 따라 오르는
    # 경우도 실제로 많기 때문에, 한쪽만 보여주면 오히려 왜곡될 수 있습니다.
    all_ranked = _rank_domestic_candidates(combined_candidates, limit=len(combined_candidates))
    already_moved = [x for x in all_ranked if x[1] or (x[2] is not None and x[2] >= 3.0)][:3]
    not_yet_moved = [x for x in all_ranked if x not in already_moved and x[2] is not None]
    not_yet_moved.sort(key=lambda x: x[2])  # 상승률 낮은(=아직 안 오른) 순
    not_yet_moved = not_yet_moved[:3]

    lines.append("✔️ 이미 반응 중인 종목 (모멘텀 확인용 - \"앞으로 오른다\"는 예측 아님)")
    if already_moved:
        for i, (name, is_upper_limit, change_pct, reasons) in enumerate(already_moved):
            change_txt = f" ({change_pct:+.2f}%)" if change_pct is not None else ""
            theme_name = name_to_theme.get(name, top_theme["name"])
            lines.append(f"{i+1}. {name}{change_txt}")
            lines.append("  근거: 미국 " + theme_name + " 강세 + " + " + ".join(reasons))
            _add_to_watchlist(name, "상한가" if is_upper_limit else "급등")  # ⏰ 급등종목도 워치리스트 등록
    else:
        lines.append("아직 뚜렷하게 반응한 종목 없음")
    lines.append("")

    lines.append("✔️ 아직 안 오른 관련주 (순환매 후보 - 참고용)")
    if not_yet_moved:
        for name, is_upper_limit, change_pct, reasons in not_yet_moved:
            change_txt = f" ({change_pct:+.2f}%)" if change_pct is not None else ""
            theme_name = name_to_theme.get(name, top_theme["name"])
            lines.append(f"• {name}{change_txt}  [{theme_name}]")
    else:
        lines.append("데이터 부족으로 판단 어려움")
    lines.append("")
    lines.append("⚠️ 참고: 위 두 목록 다 \"미국에서 같은 테마가 강했다\"는 사실 연결일 뿐,")
    lines.append("실제 미래 상승을 보장하지 않습니다. 특히 \"이미 반응 중인 종목\"은")
    lines.append("이미 오른 뒤라는 뜻이라 추격매수 위험이 있고, \"순환매 후보\"는")
    lines.append("아직 반응 안 했다는 뜻이라 아예 안 오를 수도 있습니다. 투자 판단은 본인 책임입니다.")

    # 📚 나중에 "이 테마가 뜬 날 실제로 어느 종목이 다음날 올랐는지" 백테스트를
    # 하려면, 지금부터 매일 기록을 쌓아둬야 합니다 (과거로 거슬러 만들 수는
    # 없고, 오늘부터 쌓는 수밖에 없음). Firestore에 저장, 실패해도 브리핑
    # 발송 자체는 계속 진행(기록은 부가기능이라 실패해도 안전).
    try:
        _log_briefing_for_backtest(top_theme["name"], already_moved, not_yet_moved)
    except Exception as e:
        print(f"[브리핑 기록 오류] {e}")

    return "\n".join(lines)


def _log_briefing_for_backtest(theme_name, already_moved, not_yet_moved):
    """
    오늘 브리핑에서 어떤 테마가 1순위였고, 그때 "이미 반응한 종목"/"아직 안
    오른 종목"이 뭐였는지 Firestore에 기록. 나중에(몇 주~몇 달 뒤) 이 기록과
    실제 그날그날의 결과를 대조하면, "이 테마가 뜨면 어떤 유형의 종목이
    실제로 잘 올랐는지" 통계를 낼 수 있습니다 - 지금 당장은 활용 못 하지만,
    지금부터 쌓아두지 않으면 나중에도 절대 못 만드는 데이터라 미리 시작.
    """
    if not _firestore_client:
        return
    today_str = datetime.datetime.now().strftime("%Y-%m-%d")
    doc = {
        "date": today_str,
        "top_theme": theme_name,
        "already_moved": [
            {"name": n, "change_pct": c} for n, _, c, _ in already_moved
        ],
        "not_yet_moved": [
            {"name": n, "change_pct": c} for n, _, c, _ in not_yet_moved
        ],
        "created_at": datetime.datetime.now(datetime.timezone.utc),
    }
    _firestore_client.collection("briefing_history").document(today_str).set(doc)
    print(f"✅ [브리핑 기록] {today_str} 저장 완료 (나중에 백테스트용).")


def send_morning_briefing():
    text = build_morning_briefing_text()
    if not text:
        return False
    url = f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage"
    payload = {
        "chat_id": CHAT_ID_OVERSEAS,  # 🌏 해외뉴스와 같은 채팅방으로
        "text": text,
        "link_preview_options": {"is_disabled": True},
    }
    try:
        res = requests.post(url, json=payload, timeout=10)
        if res.status_code == 200:
            print("✅ [아침 브리핑] 발송 완료.")
            return True
        print(f"[아침 브리핑 전송 실패] status={res.status_code} body={res.text[:200]}")
    except Exception as e:
        print(f"[아침 브리핑 전송 오류] {e}")
    return False


def check_morning_briefing(now):
    """
    현재 시각이 MORNING_BRIEFING_HOUR(기본 8시)대이면, 오늘 하루 한 번만
    아침 브리핑을 발송. should_run_task로 "오늘 이미 보냈는지"를 체크해서
    같은 시간대에 여러 번 호출돼도(1분마다 깨어나므로) 중복 발송 안 되게 함.
    """
    if now.hour != MORNING_BRIEFING_HOUR:
        return
    today_key = f"morning_briefing_{now.strftime('%Y%m%d')}"
    if should_run_task(today_key, 20 * 3600):  # 하루 한 번만 (20시간 이내 재실행 방지)
        send_morning_briefing()


def check_us_news(current_time_str):
    feedparser.USER_AGENT = USER_AGENT
    scanned = 0
    sent = 0
    diag_counts = {"raw": 0, "already_sent": 0, "blocked": 0, "too_old": 0, "no_match": 0}
    for rss_url in US_RSS_URLS:
        try:
            feed = _fetch_rss_feed(rss_url)
        except Exception as e:
            print(f"[해외 RSS 오류] {rss_url}: {e}")
            continue

        # 🩺 진단: 이 피드가 실제로 몇 건을 돌려줬는지 (0이면 피드 자체 문제,
        # 0이 아닌데 계속 0건 전송이면 필터링 단계 문제로 원인을 좁힐 수 있음)
        diag_counts["raw"] += len(feed.entries)
        if getattr(feed, "bozo", False):
            print(f"[해외 RSS 파싱경고] {rss_url}: {getattr(feed, 'bozo_exception', '알 수 없음')}")

        for entry in feed.entries:
            title = getattr(entry, "title", "")
            link = getattr(entry, "link", "")
            if not title:
                continue
            if is_already_sent(title):
                diag_counts["already_sent"] += 1
                continue
            if is_blocked_title(title):  # 🧹 삭제어 포함 시 무조건 차단
                diag_counts["blocked"] += 1
                mark_as_sent(title)
                continue
            if not is_recent_article(entry):
                diag_counts["too_old"] += 1
                continue

            scanned += 1
            target_hits = {kw for kw in UNIQUE_TARGET if kw.lower() in title.lower()}
            giant_hits = {kw for kw in UNIQUE_GIANTS if kw.lower() in title.lower()}
            # 🏢 영문 회사명(Samsung Electronics 등)으로만 언급된 경우도 놓치지 않도록
            # 통합 종목 인식 함수도 같이 확인 (국내뉴스와 동일한 방식)
            resolved_companies = resolve_companies_in_text(title)
            matched_count = len(target_hits | giant_hits) + len(resolved_companies)

            has_macro_word = bool(target_hits & US_MACRO_STRONG_WORDS)
            title_lower = title.lower()
            # 🚨 "속보"/"특징주"는 한글 단어라 영문 제목엔 나올 수 없어서, 영어권
            # 표현(surge/plunge/breaking 등)도 같이 확인 (버그 수정)
            is_breaking = "속보" in title or any(w in title_lower for w in US_BREAKING_WORDS)
            is_feature = "특징주" in title or any(w in title_lower for w in US_FEATURE_STOCK_WORDS)

            # 🔗 테마/실적발표 판정을 should_send 결정 "전"에 미리 해둠 - "beats
            # estimates"처럼 급등락 단어 없이 실적 얘기만 하는 제목도, 관련 테마·
            # 기업이 식별되면 그 자체로 보낼 이유가 되도록 함(막연한 "실적시즌"
            # 총평 기사까지 다 보내면 스팸이 되니, 테마/기업이 잡힐 때만 인정).
            related_theme = _detect_theme_from_text(title)
            earnings_info = _extract_earnings_info(title)
            is_earnings_worth_sending = earnings_info[0] and (related_theme or resolved_companies)

            should_send = (
                has_macro_word or matched_count >= 1 or is_breaking or is_feature  # ✏️[다시 완화] 확인용, 1개로
                or bool(resolved_companies) or is_earnings_worth_sending
            )

            if not should_send:
                mark_as_sent(title)
                continue

            # 🆕 국내뉴스와 동일하게 신규/후속/재탕을 구분함 - 재탕(새 정보 없음)만
            # 걸러내고, 후속(새 숫자/정보 있음)은 표시를 붙여서 그대로 보냄.
            novelty, novelty_emoji, novelty_note = classify_novelty(title)
            if novelty == "재탕":
                print(f"[재탕 감지] {title[:60]}")
                mark_as_sent(title)
                continue

            mark_as_sent(title)  # 🚫 먼저 등록해서 중복 전송 원천 차단
            _remember_for_fuzzy(title)
            send_telegram_message(
                title, link, current_time_str, matched_count,
                False, is_breaking, is_feature, True,
                novelty=novelty, novelty_note=novelty_note,
                related_theme=related_theme, earnings_info=earnings_info,
                target_chat_id=CHAT_ID_OVERSEAS,  # 🌏 별도 채팅방으로 보냄(설정 안 했으면 메인과 동일)
            )
            sent += 1

    print(f"[{current_time_str}] 해외 RSS: 최근 1시간 이내 신규 {scanned}건 확인, {sent}건 전송 "
          f"(원본{diag_counts['raw']}건 / 이미본것{diag_counts['already_sent']} / 삭제어{diag_counts['blocked']} / "
          f"오래됨{diag_counts['too_old']})")


# ============================================================
# 네이버 뉴스검색 API
# ============================================================
def is_recent_naver_item(pub_date_str):
    """네이버 뉴스 테스트 범위: 최근 60분(1시간)."""
    if not pub_date_str:
        return True
    try:
        article_time = parsedate_to_datetime(pub_date_str).replace(tzinfo=None)
        diff_minutes = (datetime.datetime.now() - article_time).total_seconds() / 60
        return 0 <= diff_minutes <= 60
    except Exception:
        return True



