    @app.route("/status", methods=["GET"])
    def _status_route():
        """
        🩺 소스별 상태 확인 페이지 - 로그를 스크롤하며 찾는 대신, 이 주소 하나만
        열면 각 소스(국내RSS/해외RSS/DART/네이버/텔레그램/약업전자신문 등)가
        마지막으로 언제 실행됐고 성공했는지 실패했는지(실패하면 에러 메시지까지)
        한 번에 보입니다.
        ⚠️ 컨테이너가 재시작되면 이 표도 같이 초기화됩니다(메모리 전용) -
        그러니 "방금 재시작했으면" 표가 비어있거나 최근 것만 보이는 게 정상입니다.
        """
        rows = []
        for name, info in sorted(_source_status.items()):
            status_icon = "✅" if info["ok"] else "❌"
            error_text = f" - {info['error']}" if info.get("error") else ""
            rows.append(f"<tr><td>{status_icon} {name}</td><td>{info['last_run']}</td><td>{error_text}</td></tr>")

        if not rows:
            body = "<p>아직 기록된 상태가 없습니다 (방금 재시작했거나, run_once가 아직 한 번도 안 돌았을 수 있습니다).</p>"
        else:
            body = (
                "<table border='1' cellpadding='6' style='border-collapse:collapse;'>"
                "<tr><th>소스</th><th>마지막 실행시각</th><th>에러</th></tr>"
                + "".join(rows) + "</table>"
            )

        firestore_status = "✅ 연결됨" if _firestore_client else "❌ 미연결(메모리 전용 모드 - 재시작하면 기록 초기화됨)"
        html_page = (
            "<html><body style='font-family:sans-serif;'>"
            "<h2>🩺 뉴스봇 소스별 상태</h2>"
            f"<p><b>Firestore:</b> {firestore_status}</p>"
            f"{body}"
            "<p style='color:gray;font-size:12px;'>이 페이지는 새로고침(F5)하면 최신 상태로 갱신됩니다.</p>"
            "</body></html>"
        )
        return html_page, 200

