# ============================================================
# [DART V2] 공시 일정/날짜 추출 로직
# - 공시 원문에 실제로 존재하는 날짜만 추출
# - 배당/기준일/납입일/상장일/재공시일/계약기간 등 의미별 분류
# - 없는 일정은 임의 생성하지 않음
# ============================================================
_DART_DATE = r"(20\d{2}[./-]\d{1,2}[./-]\d{1,2}|20\d{2}\s*년\s*\d{1,2}\s*월\s*\d{1,2}\s*일)"
_DART_DATE_RANGE = rf"({_DART_DATE})\s*(?:~|∼|-|부터)\s*({_DART_DATE})"

_DART_SCHEDULE_PATTERNS = [
    ("배당 기준일", [r"배당.*?기준일", r"기준일.*?배당"]),
    ("배당금 지급일", [r"배당금.*?지급일", r"지급일.*?배당금"]),
    ("배당락일", [r"배당락일"]),
    ("주주명부 폐쇄기간", [r"주주명부.*?폐쇄", r"명의개서.*?정지"]),
    ("신주배정 기준일", [r"신주.*?배정.*?기준일", r"배정기준일"]),
    ("권리락일", [r"권리락일"]),
    ("청약기간", [r"청약.*?(?:기간|일자)", r"청약일"]),
    ("납입일", [r"납입일", r"납입기일"]),
    ("신주 상장일", [r"신주.*?상장(?:예정)?일", r"상장예정일"]),
    ("변경상장일", [r"변경상장(?:예정)?일"]),
    ("전환청구기간", [r"전환청구.*?기간", r"전환청구.*?개시", r"전환청구.*?종료"]),
    ("행사기간", [r"행사.*?기간"]),
    ("전환가액 조정일", [r"전환가액.*?조정.*?일", r"조정일"]),
    ("계약일", [r"계약체결일", r"계약일"]),
    ("계약기간", [r"계약기간", r"공급기간", r"납품기간"]),
    ("계약 시작일", [r"계약.*?시작일", r"계약.*?개시일"]),
    ("계약 종료일", [r"계약.*?종료일", r"계약.*?만료일"]),
    ("투자 시작일", [r"투자.*?시작일", r"투자.*?개시일"]),
    ("투자 종료일", [r"투자.*?종료일", r"투자.*?완료일"]),
    ("준공예정일", [r"준공.*?예정일"]),
    ("잔금 지급일", [r"잔금.*?지급일"]),
    ("거래종결일", [r"거래.*?종결일", r"클로징.*?일"]),
    ("주식 취득일", [r"주식.*?취득일"]),
    ("최대주주 변경일", [r"최대주주.*?변경일"]),
    ("임상 신청일", [r"임상.*?신청일", r"IND.*?신청"]),
    ("임상 승인일", [r"임상.*?승인일", r"IND.*?승인"]),
    ("임상 개시일", [r"임상.*?개시일"]),
    ("결과 발표일", [r"결과.*?발표일", r"결과.*?공개일"]),
    ("허가 신청일", [r"허가.*?신청일"]),
    ("허가 승인일", [r"허가.*?승인일"]),
    ("최초 공시일", [r"최초.*?공시일", r"최초.*?제출일"]),
    ("정정공시일", [r"정정.*?공시일", r"정정.*?제출일"]),
    ("재공시일", [r"재공시일", r"재공시.*?예정일"]),
    ("제출일", [r"공시.*?제출일", r"제출일"]),
    ("기타 일정", [r"예정일", r"일정"]),
]

def extract_dart_schedule(text):
    """DART 원문에서 일정 정보를 의미별로 추출한다.
    원문에 없는 날짜는 생성하지 않는다.
    반환: [(라벨, 값), ...]
    """
    if not text:
        return []

    raw = re.sub(r"\s+", " ", str(text))
    found = []
    seen = set()
    used_spans = []  # (start, end) - 이미 어떤 라벨이 이 위치의 날짜를 가져갔는지 기록해서 중복/교차매칭 방지

    def norm_date(s):
        s = re.sub(r"\s+", "", s)
        s = s.replace(".", "-").replace("/", "-").replace("년", "-").replace("월", "-").replace("일", "")
        parts = s.split("-")
        if len(parts) == 3 and all(p.isdigit() for p in parts):
            y, mo, d = parts
            return f"{y}-{mo.zfill(2)}-{d.zfill(2)}"
        return s

    def overlaps_used(start, end):
        return any(not (end <= s or start >= e) for s, e in used_spans)

    # ⚠️ 라벨과 날짜 사이에 콜론(:) 없이 조사("은/는/이/가")만 붙는 자연스러운
    # 한국어 문장도 인식하도록("계약기간은 2026-01-01 ~ 2028-12-31" 같은 경우)
    _SEP = r"\s*(?:은|는|이|가)?\s*[:：]?\s*"

    # 1) '계약기간: 2026-01-01 ~ 2028-12-31' 같은 범위
    for label in ("계약기간", "공급기간", "납품기간", "전환청구기간", "행사기간",
                  "청약기간", "주주명부 폐쇄기간"):
        pat = rf"{re.escape(label)}{_SEP}{_DART_DATE_RANGE}"
        for m in re.finditer(pat, raw, re.I):
            if overlaps_used(m.start(), m.end()):
                continue
            val = f"{norm_date(m.group(2))} ~ {norm_date(m.group(3))}"
            key = (label, val)
            if key not in seen:
                found.append(key); seen.add(key)
                used_spans.append((m.start(), m.end()))

    # 2) 의미가 명시된 단일 날짜 ("라벨: 날짜" 또는 "라벨은 날짜" 순서 - 한국어
    # 공시 문서에서 압도적으로 흔한 순서라 이 방향만 안전하게 지원함.
    # ⚠️ "날짜가 먼저 나오고 라벨이 뒤에 오는" 역방향 매칭은 일부러 지원하지
    # 않습니다 - 시도해봤더니 전혀 상관없는 가까운 날짜를 엉뚱한 라벨로 잘못
    # 붙잡는 경우가 많아서(예: 청약기간 끝 날짜를 신주상장일로 오인), 없는
    # 것보다 위험하다고 판단했습니다.
    for label, patterns in _DART_SCHEDULE_PATTERNS:
        if label in {"계약기간", "공급기간", "납품기간", "전환청구기간", "행사기간",
                     "청약기간", "주주명부 폐쇄기간"}:
            continue
        for p in patterns:
            pat = rf"{p}{_SEP}({_DART_DATE})"
            for m in re.finditer(pat, raw, re.I):
                if overlaps_used(m.start(), m.end()):
                    continue
                val = norm_date(m.group(1))
                key = (label, val)
                if key not in seen:
                    found.append(key); seen.add(key)
                    used_spans.append((m.start(), m.end()))

    return found

def format_dart_schedule(text):
    items = extract_dart_schedule(text)
    if not items:
        return ""

    lines = ["⏰ 일정"]
    for label, value in items:
        lines.append(f"• {label}: {value}")
    return "\n".join(lines)



if __name__ == "__main__":
    if os.environ.get("RUN_MODE", "local") == "cloud" and app is not None:
        # Cloud Run이 컨테이너를 시작할 때 이 경로로 들어옵니다 (PORT 환경변수는 자동 지정됨).
        port = int(os.environ.get("PORT", 8080))
        app.run(host="0.0.0.0", port=port, threaded=True)
    else:
        main()

